with filtered as (select id, account_id, amount, merchant, is_flagged, cast(is_flagged as int) as is_flagged_flag, coalesce(merchant, 'NONE') as merchant_filled from transactions where txn_time > date '2023-10-05') select id, is_flagged, merchant_filled, round(amount / sum(amount) over (partition by account_id), 4) as amount_share, percent_rank() over (partition by merchant order by is_flagged_flag desc) as is_flagged_flag_percent_rank, avg(is_flagged_flag) over (partition by merchant order by is_flagged_flag, id rows between 5 preceding and 1 preceding) as is_flagged_flag_avg_5_prior, cume_dist() over (order by amount desc) as amount_cume_dist from filtered where is_flagged;
